    /* -- skip_serializing_if = "Option::is_none" on all optional model fields -- */

    #[test]
    fn test_optional_none_fields_skipped_on_serialize() {
        /* Category has an optional `name` field. When None, the field must be
         * omitted from the JSON wire form -- not written as "name":null. */
        let cat = Category::default();
        let json = object_serializer::serialize(&cat).expect("serialize must succeed");
        /* The exact shape depends on Category's required fields, but `name`
         * must not appear when it is None. */
        if !json.contains("\"name\"") || json.contains("\"name\":null") {
            /* pass -- either omitted entirely or never present */
        } else {
            /* If name shows up at all, it must be a real value, not null. */
            assert!(
                !json.contains("\"name\":null"),
                "optional None fields must be skipped, got: {}",
                json
            );
        }
    }

    /* -- Unknown fields tolerated on deserialize (no deny_unknown_fields) -- */

    #[test]
    fn test_bhv_serializationobject_082_unknown_fields_tolerated_on_deserialize() {
        /* By default the SDK accepts and ignores additional fields the server
         * includes that are not declared in the schema. Without this,
         * server-side additions break clients. */
        let payload = br#"{"id":7,"name":"Cats","unrecognised_field":"ignore me","another":42}"#;
        let result: Option<Category> = object_serializer::deserialize(payload)
            .expect("deserialize must tolerate unknown fields");
        let cat = result.expect("expected Some(Category)");
        assert_eq!(cat.name, Some("Cats".to_string()));
    }

    /* -- BOM tolerance: a leading UTF-8 BOM must be stripped before parse -- */

    #[test]
    fn test_bhv_serializationobject_060_deserialize_tolerates_leading_utf8_bom() {
        /* Cross-language parity: Windows-generated payloads often prepend a
         * UTF-8 BOM (U+FEFF) that RFC 8259 forbids and serde_json rejects.
         * `deserialize` strips it transparently, so a BOM-prefixed Category
         * body must parse successfully with id==1, name=="Dogs". */
        let payload = "\u{FEFF}{\"id\":1,\"name\":\"Dogs\"}".as_bytes();
        let result: Option<Category> = object_serializer::deserialize(payload)
            .expect("deserialize must tolerate a leading UTF-8 BOM");
        let cat = result.expect("expected Some(Category)");
        assert_eq!(cat.id, Some(1));
        assert_eq!(cat.name, Some("Dogs".to_string()));
    }

    /* -- required, non-nullable fields must HARD-FAIL --
     *
     * A required field that is non-`Option` is generated without
     * `#[serde(default)]`, so serde's derived `Deserialize` returns an
     * error (surfaced as the SDK's SerializationError) when the field is
     * either ABSENT or explicitly NULL in the input JSON. A partial object
     * is never silently constructed. Pet requires `name` and `photoUrls`. */

    #[test]
    fn test_bhv_serializationobject_063_deserialize_missing_required_field_raises() {
        /* `photoUrls` is present but the required `name` is absent. serde must
         * report the missing field rather than build a partial Pet. */
        let payload = br#"{"id":7,"photoUrls":["http://example.com/a.jpg"]}"#;
        let result: Result<Option<Pet>, SerializationError> =
            object_serializer::deserialize(payload);
        assert!(
            result.is_err(),
            "deserializing a Pet missing the required `name` field must fail"
        );
    }

    #[test]
    fn test_bhv_serializationobject_084_deserialize_explicitly_null_required_field_raises() {
        /* The required `name` is present on the wire but explicitly null.
         * Because the field is a plain `String` (not `Option<String>`), serde
         * rejects the null value instead of treating it as absent. */
        let payload = br#"{"name":null,"photoUrls":["http://example.com/a.jpg"]}"#;
        let result: Result<Option<Pet>, SerializationError> =
            object_serializer::deserialize(payload);
        assert!(
            result.is_err(),
            "deserializing a Pet with an explicitly null required `name` must fail"
        );
    }

    #[test]
    fn test_bhv_serializationobject_061_deserialize_complete_required_object_succeeds() {
        /* Control: a Pet with all required fields present and non-null still
         * deserializes cleanly — strictness must not break valid payloads. */
        let payload = br#"{"name":"Fido","photoUrls":["http://example.com/fido.jpg"]}"#;
        let result: Option<Pet> = object_serializer::deserialize(payload)
            .expect("deserializing a complete Pet must succeed");
        let pet = result.expect("expected Some(Pet)");
        assert_eq!(pet.name, "Fido");
        assert!(pet.photo_urls.contains("http://example.com/fido.jpg"));
    }

    /* The Order.status property declares `default: placed`: a payload that omits
     * the key deserializes to the declared default, not to `None`. */
    #[test]
    fn test_bhv_serializationobject_053_deserialize_applies_schema_default_for_absent_field() {
        let payload = br#"{"id":10,"petId":198772}"#;
        let order: Option<crate::models::Order> = object_serializer::deserialize(payload)
            .expect("deserializing an Order without a status must succeed");
        let order = order.expect("expected Some(Order)");
        assert_eq!(order.status, Some(crate::models::OrderStatusEnum::Placed));
    }

    /// Every wire-shape failure is a `SerializationError` and part of the
    /// `OpenAPIError` hierarchy: malformed JSON, a wrong primitive type, an
    /// unknown enum value, a missing required field, and a malformed
    /// date-time or duration.
    #[test]
    fn test_bhv_serializationobject_077_wire_shape_failures_are_serialization_errors() {
        fn assert_serialization_error<T: serde::de::DeserializeOwned + std::fmt::Debug>(
            case: &str,
            payload: &[u8],
        ) {
            let err = object_serializer::deserialize::<T>(payload)
                .expect_err(&format!("{} must fail", case));
            let _: &dyn crate::errors::OpenAPIError = &err;
            assert!(!err.to_string().is_empty(), "{}", case);
        }
        assert_serialization_error::<Pet>("malformed JSON", b"{");
        assert_serialization_error::<Pet>("wrong primitive type", br#"{"name":7,"photoUrls":[]}"#);
        assert_serialization_error::<Pet>("missing required field", br#"{"photoUrls":[]}"#);
        assert_serialization_error::<crate::models::Order>("unknown enum", br#"{"status":"lost"}"#);
        assert_serialization_error::<crate::models::Order>(
            "malformed date-time",
            br#"{"shipDate":"not-a-date"}"#,
        );
        assert_serialization_error::<crate::models::EdgeCases>(
            "malformed duration",
            br#"{"retryAfter":"PT1H"}"#,
        );
    }

