    /* A repeated key resolves to its last value, as in the other SDKs, rather
     * than failing with serde's "duplicate field" error. */
    #[test]
    fn test_bhv_serializationobject_006_deserialize_duplicate_key_keeps_the_last_value() {
        let payload = br#"{"id":1,"name":"first","id":2}"#;
        let category: Option<Category> =
            object_serializer::deserialize(payload).expect("deserialize must succeed");
        let category = category.expect("expected Some(Category)");
        assert_eq!(category.id, Some(2));
        assert_eq!(category.name.as_deref(), Some("first"));
    }

    #[test]
    fn test_deserialize_duplicate_key_still_rejects_trailing_content() {
        let payload = br#"{"id":1,"id":2} trailing"#;
        let result: Result<Option<Category>, _> = object_serializer::deserialize(payload);
        assert!(result.is_err(), "trailing content must still be rejected");
    }

    /* A discriminator-tagged payload deserialized against the parent PetFood
     * oneOf enum must resolve to the concrete DryFood variant via PetFood's
     * custom Deserialize routing on foodType="dry", not fall through to a
     * silent untagged match. */
    #[test]
    fn test_bhv_serializationobject_055_deserialize_parent_routes_to_subtype() {
        let payload = br#"{"foodType":"dry","weightKg":2.5}"#;
        let result: Option<PetFood> =
            object_serializer::deserialize(payload).expect("deserialize must succeed");
        match result.expect("expected Some(PetFood)") {
            PetFood::DryFood(dry) => assert_eq!(dry.weight_kg, 2.5),
            other => panic!("expected PetFood::DryFood, got: {other:?}"),
        }
    }

    /* JSON `null` on a required, non-nullable field must HARD-FAIL
     * deserialization. The payload `{"name": null, "photoUrls": ["u"]}` sets
     * the required `name` (a plain `String`, not `Option<String>`) to JSON
     * null. serde's derived `Deserialize` rejects the null because the field is
     * non-Option, surfacing the SDK's SerializationError rather than silently
     * constructing a Pet with an empty/partial `name`. */
    #[test]
    fn test_bhv_serializationobject_062_null_on_required_field_rejected() {
        let payload = br#"{"name":null,"photoUrls":["u"]}"#;
        let result: Result<Option<Pet>, SerializationError> =
            object_serializer::deserialize(payload);
        assert!(
            result.is_err(),
            "null on the required non-nullable `name` must be rejected"
        );
    }

    /* A discriminator value the spec does not list, or an empty one, must
     * HARD-FAIL as a SerializationError that names the problem, never dispatch
     * to a variant whose fields happen to fit. */
    #[test]
    fn test_unknown_and_empty_discriminator_rejected() {
        let unknown: Result<Option<PetFood>, SerializationError> =
            object_serializer::deserialize(br#"{"foodType":"raw","calories":300}"#);
        let err = unknown.expect_err("an unlisted discriminator value must be rejected");
        assert!(
            err.to_string()
                .contains("unknown discriminator value `raw` for PetFood"),
            "unexpected message: {}",
            err
        );

        let empty: Result<Option<PetFood>, SerializationError> =
            object_serializer::deserialize(br#"{"foodType":"","weightKg":2.5}"#);
        let err = empty.expect_err("an empty discriminator value must be rejected");
        assert!(
            err.to_string()
                .contains("unknown discriminator value `` for PetFood"),
            "unexpected message: {}",
            err
        );

        let missing: Result<Option<PetFood>, SerializationError> =
            object_serializer::deserialize(br#"{"weightKg":5.0}"#);
        let err = missing.expect_err("a missing discriminator must be rejected");
        assert!(
            err.to_string()
                .contains("missing discriminator field `foodType` for PetFood"),
            "unexpected message: {}",
            err
        );
    }

    /* A discriminated oneOf payload that omits the discriminator property must
     * HARD-FAIL, not wrap the raw object in a union container. The payload
     * `{"weightKg": 5.0}` omits `foodType`; PetFood's hand-rolled Deserialize
     * reads the discriminator field and returns an Err when it is absent
     * (rather than serde-untagged's "try every variant" fall-through). */
    #[test]
    fn test_bhv_serializationobject_085_missing_discriminator_rejected() {
        let payload = br#"{"weightKg":5.0}"#;
        let result: Result<Option<PetFood>, SerializationError> =
            object_serializer::deserialize(payload);
        assert!(
            result.is_err(),
            "PetFood missing the `foodType` discriminator must be rejected"
        );
    }

    #[test]
    fn test_bhv_serializationobject_008_uri_property_accepts_any_absolute_uri_and_rejects_relative_references(
    ) {
        for uri in [
            "urn:isbn:0451450523",
            "mailto:a@b.com",
            "ftp://x.org/f",
            "https://example.com/items/1",
        ] {
            let payload =
                String::from(r#"{"name":"n","photoUrls":[],"homepageUrl":""#) + uri + r#""}"#;
            let pet: Pet = object_serializer::deserialize(payload.as_bytes())
                .unwrap_or_else(|e| panic!("{} must decode: {}", uri, e))
                .expect("expected Some");
            assert_eq!(pet.homepage_url.as_deref(), Some(uri));
            let json = object_serializer::serialize(&pet).expect("serialization failed");
            assert!(
                json.contains(&format!(r#""homepageUrl":"{}""#, uri)),
                "got: {}",
                json
            );
        }
        for bad in ["/relative", "not a uri", ""] {
            let payload =
                String::from(r#"{"name":"n","photoUrls":[],"homepageUrl":""#) + bad + r#""}"#;
            let result: Result<Option<Pet>, SerializationError> =
                object_serializer::deserialize(payload.as_bytes());
            assert!(result.is_err(), "{:?} must be rejected", bad);
        }
        let reference: Pet = object_serializer::deserialize(
            br#"{"name":"n","photoUrls":[],"thumbnailRef":"/assets/thumb-1.png"}"#,
        )
        .expect("a uri-reference keeps relative references")
        .expect("expected Some");
        assert_eq!(
            reference.thumbnail_ref.as_deref(),
            Some("/assets/thumb-1.png")
        );
    }

